import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"周易口诀义 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"周易口诀义 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/031.md","filePath":"zh/classics/koujueyi/031.md"}'),r={name:"zh/classics/koujueyi/031.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>彖曰：「习坎」，重险也。水流而不盈，行险而不失其信。「维心亨」，乃以刚中也；「行有尚」，往有功也。天险，不可升也；地险，山川丘陵也。王公设险以守其国，险之时用大矣哉！象曰：水瀳至，「习坎」。君子以常德行，习教事。</p><p>初六：「习坎」，入于坎窞，凶。</p><p>象曰：「习坎」入坎，失道凶也。</p><p>九二：坎有险，求小得。</p><p>象曰：「求小得」，未出中也。</p><p>六三：来之坎坎，险且枕，入于坎窞，勿用。</p><p>象曰：「来之坎坎」，终无功也。</p><p>六四：樽酒簋贰，用缶，纳约自牖，终无咎。</p><p>象曰：「樽酒簋贰」，刚柔际也。</p><p>九五：坎不盈，祗既平，无咎。</p><p>象曰：「坎不盈」，中未大也。</p><p>上六：系用徽𬙊，置于丛棘，三岁不得，凶。</p><p>象曰：上六失道，凶三岁也。</p><p>解读</p><p>「习坎」者，习为便习也；「坎」，险陷也。夫险难之事，非经便习不可以行，故加「习坎」之字。「有孚维心亨」者，维于险难之中而有刚中之质，故其孚信维系于心，所以通也。行有尚者，内心刚正，信实不失，以此而行，人所尊尚也。象曰：「水瀳至，习坎」者，瀳，因仍也。雨水因仍，相瀳而至，故重险。「君子以常德行，习教事」者，王君云：至险未夷，教不可废，维处险难之中，以恒常德行，习修政教之事，故庄氏云「虽处急难之时，道教岂可忘哉」是也。</p><p>「初六，习坎，入于坎窞，凶」者，「习坎」，犹其始习险事；「窞」，坎底也。处坎之底，无人救援，失道而穷，所以「凶」也。</p><p>「九二，坎有险，求小得」者，实德无应，犹处险中，故曰「坎有险」也。与初三相近，缘初三阴柔，皆是小人，不足以为大援，故只可「求小得」也。</p><p>「六三，来之坎坎，险且枕，入于坎窞，勿用」者，位既不正，又居两「坎」之间，来之与往，皆入于「坎」，故曰「来之坎坎」也。「枕」者，不安之貌，出即无应，居又不安，故曰「险且枕」也；往来皆危，入于坎底，故曰「入于坎窞」也；失位无应，虽复往来，徒劳而已，故曰「勿用」也。</p><p>「六四：樽酒、簋贰，用缶，纳约自牖，终无咎」者，以柔得位，上奉于君，君臣相亲时，明信显著，虽复一樽之酒，二簋之食，而用瓦缶，为此俭约，进献于牖，明德惟馨，故「终无咎」也。</p><p>「九五：坎不盈，祗既平，无咎」者，独陷难中，而无救助，是无匡弼之臣，故曰「坎不盈」也。身处尊位，不可安然，必须释难济时，使天下安平，乃得无咎。故书云「其尔万方有罪，在予一人」是也。</p><p>上六：系用徽𬙊，置于丛棘，三岁不得，凶者，徽𬙊犹墨索也。上六处险之极，即是犯于严法之人，遂乃以徽墨之绳而系䌸之，置于丛棘之中，令其思过矣。虞氏云：「以置九棘，取改过自新，故曰系用徽𬙊，置于丛棘也。」若置之九棘之中，而不能改过自新，必致罪咎，故曰「三岁不得，凶」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
